{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — for example, minimize the number of containers used, maximize the total weight of goods shipped, or something else?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific objective of the packing plan, presented as a choice among examples."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are all available units of each goods type required to be shipped, or is it acceptable to leave some units unshipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding shipping requirements."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the objective is to minimize the number of containers and it's acceptable to leave goods unshipped, is there a requirement that a minimum amount of goods must be shipped, or is it theoretically acceptable to ship nothing (using zero containers)?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the minimum shipment requirement."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the conditional rule \"if a container contains any type A then it must also contain at least one type C\" — does this apply to every container that has at least one unit of A, meaning a container with 1 unit of A still needs at least 1 unit of C?"
  ],
  "rationale": "The response asks a single clarification question regarding the scope of a conditional rule, specifically whether it applies to containers with a single unit of type A."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum number of containers available, or can we use as many containers as needed as long as each is loaded between 18 and 60 tons?"
  ],
  "rationale": "The response asks for a single policy choice regarding the availability limit of containers, presenting two mutually exclusive options in one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Regarding the minimum 12 units of type D per container — does this apply to every container that is used, including containers that might not contain any type A?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation on the scope of a constraint."
}

{
  "action": "question",
